fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap() // Safely unwrap since the array is non-empty
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap() // Safely unwrap since the array is non-empty
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");
    
    let mut sorted_a = a.clone(); // Clone the array to sort it
    sorted_a.sort(); // Sort the array

    let n = sorted_a.len();
    
    if q == 0 {
        return get_min_val(&sorted_a);
    } else if q == 100 {
        return get_max_val(&sorted_a);
    } else {
        // Calculate the index for the quantile
        let index = (q as usize * (n - 1)) / 100; // Use usize for indexing
        return sorted_a[index];
    }
}